from pathlib import Path
import json,sys
b=Path(__file__).parent;e=b/'evidence';root=b.parents[1];sys.path.insert(0,str(root/'tools'))
from http_evidence import save_excerpt
specs=[
('M01','github-documentation','Getting permanent links / Press Y','Q4,Q5,Q6','Commit ID binds the selected file version; a branch-head file can change. This fixes the file content, not external links embedded inside it.','put a commit ID','File-link policy; no guarantee that external linked resources are pinned or the repository remains accessible.'),
('M02','github-documentation','Viewing HTML elements / Rendering differences','Q3,Q4,Q5','GitHub distinguishes source and rendered views and documents that HTML commit rich views are not directly supported. The R1/R2 live browser observations independently establish source display for these exact blob URLs.',"We don't directly support rendered views of commits to HTML documents.",'The cited policy section concerns commit/diff rendering. Do not generalize it alone into a comprehensive MIME policy for all raw URLs.'),
('M03','whatwg-html','2.4.3 Document base URLs','Q2,Q4,Q5','HTML URL resolution uses the first base element with href, otherwise the document fallback URL (subject to override/about-document cases). Identical HTML at a different base can resolve relative resources differently.','first such base element in tree order','Normative resolution rule, not proof of any target payload availability. GitHub code is text, so source href is not automatically a live anchor.'),
('M04','pkgdown-documentation','External files; Output formats','Q4,Q5,Q6','pkgdown copies linked images via external-resource detection; resource_files can explicitly list files when detection fails. Independently hosted Shiny iframes are described separately. A page file and a complete resource set are different preservation units.','copy any images that you link to','Current documentation does not prove how archive/asciicast historical files were built. No build was executed.'),
('M05','readthedocs-documentation','URL schemes; How to change','Q3,Q4,Q6','RTD permits multi-version paths with language/version prefixes and single-version roots. Changing a versioning scheme can break existing links unless redirects are provided. URL structure is configuration, not a content-version attestation.','any existing links to your documentation will break','General current policy; no inference that this configuration change caused P1 named404.'),
('M06','mkdocs-documentation','Linking to pages; file layout','Q4,Q5,Q6','MkDocs rewrites links to source Markdown into HTML output paths, adjusts relative paths, and leaves absolute paths unchanged. Source URI and generated URI are not interchangeable. Header fragments are preserved while the path is transformed.','Relative paths are adjusted by MkDocs','Current help; does not prove historical generator behavior or make an external destination same-version.'),
('M07','sphinx-documentation','Referencing downloadable files / download role','Q4,Q5,Q6','Sphinx download role copies referenced downloadable files into a hashed _downloads directory and emits a link for HTML output. This is a concrete way to preserve a document plus next file rather than only its source URI.','All downloadable files are put into a','General documented mechanism; the existence of a role in source does not itself prove the output resource exists in a given project build.')]
rows=[]
for rid,lineage,section,qs,ob,quote,limit in specs:
 r=json.loads((e/(rid+'.receipt.json')).read_text()); raw=(e/'raw'/(rid+'.txt')).read_text(); assert quote in raw,(rid,quote)
 save_excerpt(e,rid,ob,[quote])
 row={'source_id':rid,'work_id':lineage,'lineage_id':lineage,'category':'method','original_url':r['requested_url'],'published_utc':None,'retrieved_utc':r['retrieved_utc'],'version':'current document at retrieval; SHA256 pinned in receipt','location':section,'questions':qs.split(','),'cases':['P3','P1','R1','R2'],'observation':ob,'excerpt':quote,'fingerprint':{'sha256':r['sha256'],'body_bytes':r['body_bytes']},'support_refute':'supports bounded link/content distinctions; refutes automatic transitive version guarantees','limitations':limit+' Publication UTC unspecified.','reread_url':r['requested_url'],'eligible':r['status']==200,'receipt_path':str((e/(rid+'.receipt.json')).relative_to(root)),'excerpt_path':str((e/(rid+'.excerpt.json')).relative_to(root))}
 rows.append(row)
(b/'sources.jsonl').write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in rows))
(b/'findings.md').write_text('# 공식 생성·호스팅·상대 경로 근거\n\n'+''.join(f"- **{r['source_id']}** [{r['location']}]({r['original_url']}): {r['observation']} 한계: {r['limitations']}\n" for r in rows)+'\n직접7자료, 독립 문서계보6. 이 자료는 실제4자리 응답 판정을 대신하지 않는다.\n')
print({'direct_sources':len(rows),'lineages':len({x['lineage_id'] for x in rows})})
